def prime_order(base, modulus):
    if math.gcd(base, modulus) != 1:
        return 0
    phi = modulus - modulus // base if base > 1 else modulus - 1
    if modulus == 1:
        return 1

    # Calculate Euler's totient function phi(modulus)
    def euler_phi(n):
        result = n
        p = 2
        temp_n = n
        while p * p <= temp_n:
            if temp_n % p == 0:
                while temp_n % p == 0:
                    temp_n //= p
                result -= result // p
            p += 1
        if temp_n > 1:
            result -= result // temp_n
        return result

    phi_m = euler_phi(modulus)

    # Find the prime factorization of phi_m
    factors = []
    n = phi_m
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)

    # Test divisors of phi_m
